19	const REQUIRED = ['--a', '--b', '--c'];
20	const KNOWN = new Set(REQUIRED);
21	
22	function fail(message) {
23	  process.stderr.write(USAGE + '\n');
24	  process.stderr.write(`${PROG}: error: ${message}\n`);
25	  process.exit(2);
