36	export function parseArgs(argv) {
37	  const values = { '--a': null, '--b': null, '--c': null };
38	  const extras = [];
39	
40	  for (let i = 0; i < argv.length; i++) {
41	    const token = argv[i];
42	
43	    if (token === '-h' || token === '--help') {
44	      process.stdout.write(HELP);
45	      process.exit(0);
46	    }
47	
48	    // Split "--x=value" into option and inline value; otherwise the value
49	    // is the next token ("--x value" form).
50	    let opt = token;
51	    let inlineValue = null;
52	    const eq = token.indexOf('=');
53	    if (token.startsWith('--') && eq !== -1) {
54	      opt = token.slice(0, eq);
55	      inlineValue = token.slice(eq + 1);
56	    }
57	
58	    if (!KNOWN.has(opt)) {
59	      extras.push(token);
60	      continue;
61	    }
62	
63	    let value;
64	    if (inlineValue !== null) {
65	      value = inlineValue;
66	    } else if (i + 1 < argv.length) {
67	      value = argv[++i];
68	    } else {
69	      fail(`argument ${opt}: expected one argument`);
70	    }
