function parsePythonInt(raw) {
  const s = raw.trim();
  if (!/^[+-]?\d+$/.test(s)) return null;
  return parseInt(s, 10);
}

// argparse treats a token as an option string (not a value) when it starts
// with '-', is longer than one char, and does not look like a negative
// number (no options here look like negative numbers).
function looksLikeOption(token) {
  return token.length > 1 && token.startsWith('-') && !/^-\d+$|^-\d*\.\d+$/.test(token);
}

