9	/**
10	 * Derives a key using PBKDF2 with HMAC-SHA1 as the PRF.
11	 *
12	 * @param {Uint8Array} password - The password, as bytes.
13	 * @param {Uint8Array} salt - The salt, as bytes.
14	 * @param {number} iterations - Iteration count (c), a positive integer.
15	 * @param {number} dkLen - Desired derived key length in bytes.
16	 * @returns {Uint8Array} The derived key, exactly dkLen bytes long.
17	 */
18	export function pbkdf2Sha1(password, salt, iterations, dkLen) {
19	  if (!Number.isInteger(iterations) || iterations < 1) {
20	    throw new RangeError('iterations must be a positive integer');
21	  }
22	  if (!Number.isInteger(dkLen) || dkLen < 0) {
23	    throw new RangeError('dkLen must be a non-negative integer');
24	  }
25	
26	  const blockCount = Math.ceil(dkLen / H_LEN);
27	  // RFC 2898: dkLen must not exceed (2^32 - 1) * hLen.
28	  if (blockCount > 0xffffffff) {
29	    throw new RangeError('derived key too long');
30	  }
31	
32	  const derivedKey = new Uint8Array(blockCount * H_LEN);
33	
34	  // salt || INT_32_BE(i), reused for every block.
35	  const blockInput = new Uint8Array(salt.length + 4);
36	  blockInput.set(salt, 0);
37	
38	  for (let i = 1; i <= blockCount; i++) {
39	    // INT_32_BE(i): encode block index as 4-byte big-endian.
40	    blockInput[salt.length] = (i >>> 24) & 0xff;
41	    blockInput[salt.length + 1] = (i >>> 16) & 0xff;
42	    blockInput[salt.length + 2] = (i >>> 8) & 0xff;
43	    blockInput[salt.length + 3] = i & 0xff;
44	
45	    // U1 = PRF(password, salt || INT_32_BE(i))
46	    let u = hmacSha1(password, blockInput);
47	    const t = new Uint8Array(u);
48	
49	    // Uj = PRF(password, U(j-1)); T = U1 xor U2 ... xor Uc
50	    for (let j = 2; j <= iterations; j++) {
51	      u = hmacSha1(password, u);
52	      for (let k = 0; k < H_LEN; k++) {
53	        t[k] ^= u[k];
54	      }
55	    }
56	
57	    derivedKey.set(t, (i - 1) * H_LEN);
58	  }
59	
60	  return derivedKey.subarray(0, dkLen);
61	}

