**`/output/sha1.mjs`** — 纯 JS SHA-1：

```js
// Pure-JS SHA-1 (FIPS 180-1) for Node.js ESM. No external dependencies.

const K = [0x5a827999, 0x6ed9eba1, 0x8f1bbcdc, 0xca62c1d6];

function rotl(x, n) {
  return ((x << n) | (x >>> (32 - n))) >>> 0;
}

export function sha1(data) {
  const msgLen = data.length;
  const bitLen = msgLen * 8;

  // MD strengthening: append 0x80, pad with zeros until 56 mod 64,
  // then append the 64-bit big-endian message length in bits.
  const paddedLen = (msgLen + 9 + 63) & ~63;
  const buf = new Uint8Array(paddedLen);
  buf.set(data);
  buf[msgLen] = 0x80;
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  const v = new DataView(buf.buffer);
  v.setUint32(paddedLen - 8, hi);
  v.setUint32(paddedLen - 4, lo);

  let h0 = 0x67452301, h1 = 0xefcdab89, h2 = 0x98badcfe,
      h3 = 0x10325476, h4 = 0xc3d2e1f0;
  const w = new Uint32Array(80);

  for (let off = 0; off < paddedLen; off += 64) {
    for (let t = 0; t < 16; t++) w[t] = v.getUint32(off + t * 4);
    for (let t = 16; t < 80; t++)
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);

    let a = h0, b = h1, c = h2, d = h3, e = h4;
    for (let t = 0; t < 80; t++) {
      let f, k;
      if (t < 20)      { f = (b & c) | (~b & d);          k = K[0]; }
      else if (t < 40) { f = b ^ c ^ d;                   k = K[1]; }
      else if (t < 60) { f = (b & c) | (b & d) | (c & d); k = K[2]; }
      else             { f = b ^ c ^ d;                   k = K[3]; }
      const tmp = (rotl(a, 5) + f + e + k + w[t]) >>> 0;
      e = d; d = c; c = rotl(b, 30); b = a; a = tmp;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0; h4 = (h4 + e) >>> 0;
  }

  const out = new Uint8Array(20);
  const ov = new DataView(out.buffer);
  ov.setUint32(0, h0); ov.setUint32(4, h1); ov.setUint32(8, h2);
  ov.setUint32(12, h3); ov.setUint32(16, h4);
  return out;
}
```

**`/output/hmac.mjs`** — RFC 2104 HMAC-SHA1：

```js
// HMAC-SHA1 per RFC 2104, implemented from scratch in pure JS.
// Relies only on the local ./sha1.mjs implementation.

import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64;

export function hmacSha1(key, message) {
  let k = key;
  if (k.length > BLOCK_SIZE) k = sha1(k);
  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(k);

  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  const outerPad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    inner[i] = paddedKey[i] ^ 0x36;
    outerPad[i] = paddedKey[i] ^ 0x5c;
  }
  inner.set(message, BLOCK_SIZE);

  const innerHash = sha1(inner);
  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(outerPad, 0);
  outer.set(innerHash, BLOCK_SIZE);
  return sha1(outer);
}
```

**`/output/pbkdf2.mjs`** — PBKDF2 (RFC 2898)，标准 `U1 = PRF(P, S || INT32_BE(i))`、`T = U1⊕…⊕Uc` 构造（完整代码见文件，61 行）。

**`/output/args.mjs`** — 手写解析 `--a/--b/--c`，支持 `--x value` 与 `--x=value`，并逐项复刻了 argparse 行为：缺必填项/非法 int（含 Python `int()` 的下划线与空白语义）/未知参数均输出相同 usage + error 并 exit 2；`-h` 输出与 argparse 一致的 help 并 exit 0。

